import pandas as pd
import numpy as np

train = pd.read_csv('train.csv')
features = [c for c in train.columns if c != 'target']
X = train[features].values
y = train['target'].values.astype(float)

class DecisionTreeRegressor:
    def __init__(self, max_depth=3):
        self.max_depth = max_depth
        self.tree = None

    def fit(self, X, y):
        self.tree = self._build_tree(X, y, 0)

    def _build_tree(self, X, y, depth):
        n_samples, n_features = X.shape
        if depth >= self.max_depth or n_samples < 2 or np.all(y == y[0]):
            return np.mean(y)

        best_split = None
        best_mse = float('inf')

        # sample features
        feat_idxs = np.random.choice(n_features, min(15, n_features), replace=False)

        for feature in feat_idxs:
            thresholds = np.percentile(X[:, feature], np.linspace(10, 90, 10))
            for threshold in thresholds:
                left_mask = X[:, feature] <= threshold
                right_mask = ~left_mask
                if np.sum(left_mask) == 0 or np.sum(right_mask) == 0:
                    continue

                left_y = y[left_mask]
                right_y = y[right_mask]

                # We want to minimize variance (MSE)
                mse = np.var(left_y) * len(left_y) + np.var(right_y) * len(right_y)

                if mse < best_mse:
                    best_mse = mse
                    best_split = {
                        'feature': feature,
                        'threshold': threshold,
                        'left_mask': left_mask,
                        'right_mask': right_mask
                    }

        if best_split is None:
            return np.mean(y)

        left_branch = self._build_tree(X[best_split['left_mask']], y[best_split['left_mask']], depth + 1)
        right_branch = self._build_tree(X[best_split['right_mask']], y[best_split['right_mask']], depth + 1)

        return {'feature': best_split['feature'], 'threshold': best_split['threshold'],
                'left': left_branch, 'right': right_branch}

    def predict(self, X):
        return np.array([self._predict_one(x, self.tree) for x in X])

    def _predict_one(self, x, tree):
        if not isinstance(tree, dict):
            return tree
        if x[tree['feature']] <= tree['threshold']:
            return self._predict_one(x, tree['left'])
        else:
            return self._predict_one(x, tree['right'])

print("Training simple tree...")
tree = DecisionTreeRegressor(max_depth=5)
n_train = 10000
tree.fit(X[:n_train], y[:n_train])
preds = tree.predict(X[n_train:n_train+5000])
acc = np.mean((preds >= 0.5) == y[n_train:n_train+5000])
print(f"Tree Accuracy: {acc}")
